<script setup lang="ts">
import type {DecorationBlock,DecorationProfile,DecorationLink,DecorationMember} from '../../../../api/src/core/decoration-types'
import {frameworkAsset} from '../../../../api/src/core/decoration-framework.mjs'
import {decorationOptions} from '../../../../api/src/core/decoration-options.mjs'
import {decorationProfile} from '../../../../api/src/core/decoration-components.mjs'
const props=defineProps<{block:DecorationBlock;profile?:DecorationProfile|null;member?:DecorationMember|null;editable?:boolean;imageUrl:(id:string)=>string}>()
defineEmits<{navigate:[target:DecorationLink]}>()
const o=computed(()=>decorationOptions(props.block))
const identity=computed(()=>decorationProfile(props.profile===undefined?{nickname:'小林',account:'user001',memberNumber:'HY00000001'}:props.profile))
const memberLabel=computed(()=>props.member?.level?.name||'普通会员')
</script>
<template><button type="button" class="profile-header" :class="{center:o.profileLayout==='center','profile-banner':o.profileLayout==='banner'}" :style="o.profileLayout==='banner'?{minHeight:'calc(var(--diy-unit,1px)*'+o.profileHeight+')',backgroundImage:'url('+(block.imageId?imageUrl(block.imageId):frameworkAsset('intro.webp'))+')'}:{}" :disabled="editable||!block.target" @click="$emit('navigate',block.target)"><span v-if="o.showAvatar" class="profile-avatar"><img :src="identity.avatar||frameworkAsset('avatar.webp')" alt="用户头像"></span><span class="profile-info"><span class="profile-name-row"><strong>{{identity.name}}</strong><span v-if="profile!==null" class="profile-badge">{{memberLabel}}</span></span><span v-if="o.showAccount&&identity.account" class="profile-detail">账号：{{identity.account}}</span><span v-if="o.showMemberNumber&&identity.memberNumber" class="profile-detail">ID：{{identity.memberNumber}}</span></span></button></template>
